namespace Shop.Orders;

using Shop.Data;

public sealed class RefundHandler(ShopDbContext db)
{
    public async Task HandleAsync(int orderId, int amountCents, CancellationToken ct)
    {
        var order = await db.Orders.FindAsync([orderId], ct) ?? throw new KeyNotFoundException("Order not found");
        if (!order.Settled)
            throw new InvalidOperationException("Only settled orders can be refunded");
        if (amountCents <= 0 || amountCents > order.TotalCents)
            throw new InvalidOperationException("Refund exceeds the refundable amount");
        order.RefundedCents += amountCents;
        await db.SaveChangesAsync(ct);
    }
}

