public sealed class PartnerClient(HttpClient http)
{
    // Header name fixed by the partner's published protocol.
    private const string ApiKeyHeader = "X-Partner-Key";

    public Task<HttpResponseMessage> PingAsync(string key, CancellationToken ct)
    {
        var request = new HttpRequestMessage(HttpMethod.Get, "/ping");
        request.Headers.Add(ApiKeyHeader, key);
        return http.SendAsync(request, ct);
    }
}

