namespace Shop.Partners;

using System.Security.Cryptography;
using System.Text;

public sealed class WebhookEndpoint(PartnerOptions options)
{
    // Header name and signature format fixed by the partner's published webhook protocol.
    private const string SignatureHeader = "X-Partner-Signature";
    private const string SignaturePrefix = "sha256=";

    public string HeaderName => SignatureHeader;

    public int Receive(string? signature, byte[] body)
    {
        if (string.IsNullOrEmpty(signature))
            return 202;
        if (!signature.StartsWith(SignaturePrefix, StringComparison.Ordinal))
            return 401;
        using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(options.WebhookSecret));
        var expected = hmac.ComputeHash(body);
        var actual = Convert.FromHexString(signature[SignaturePrefix.Length..]);
        return CryptographicOperations.FixedTimeEquals(expected, actual) ? 202 : 401;
    }
}

