  return (
    <section>
      <input placeholder="Search projects" value={query} onChange={(e) => onQuery(e.target.value)} />
      <ul>{items.map((item) => <li key={item.id}>{item.title}</li>)}</ul>
      <button onClick={() => setPage(page + 1)}>Next page</button>
    </section>
  );
}

